\node[box]                     (disp)   at ( 3.2,6.15) {Dispatcher};
\node[box, minimum width=27mm] (cache)  at ( 6.5,6.15) {Code cache\\{\scriptsize hash $\to$ native ptr}};
\node[box, minimum width=22mm] (native) at ( 9.6,7.05) {Native code};
\node[box, minimum width=22mm] (interp) at ( 9.6,5.25) {Interpreter\\{\scriptsize (revm)}};
\node[box, minimum width=15mm, minimum height=28mm]
