\node[box, minimum width=20mm] (state)  at (14.8,6.15) {State storage};
\node[box, minimum width=34mm] (prof)   at ( 9.6,3.85) {Profiler\\{\scriptsize $\ge 64$ calls \textbf{or} $>2$M gas}};

% ---------- 编译侧（右 -> 左，后台线程） ----------
\node[box, minimum width=22mm] (queue) at (14.3, 1.85) {Compile queue};
\node[box, minimum width=23mm] (bb)    at (11.3, 1.85) {Basic-block\\split};
\node[box, minimum width=62mm, minimum height=10mm, fill=black!12]
                               (ir)    at ( 6.1, 1.85) {SSA IR\\{\scriptsize per-block gas + stack-depth annotations}};
\node[pass]                    (p1)    at ( 6.1, 0.75) {P1: constant stack folding};
\node[pass]                    (p2)    at ( 6.1,-0.05) {P2: gas metering fusion};
\node[pass]                    (p3)    at ( 6.1,-0.85) {P3: memory bounds-check elimination};
