% ---------- 分区（背景层：先大框后重点框，避免填充互盖） ----------
\begin{scope}[on background layer]
  \node[draw=black!55, dashed, rounded corners=3pt, fill=black!3, inner sep=6mm,
        fit=(queue)(bb)(ir)(p3)(jit)] (bgbox) {};
  \node[draw, line width=1.2pt, rounded corners=3pt, fill=black!5, inner sep=2.5mm,
        fit=(ir)(p1)(p2)(p3)] (irbox) {};
\end{scope}
\node[lbl, anchor=south west, font=\scriptsize\itshape] at (bgbox.north west)
      {background compiler thread (asynchronous)};

% ---------- 执行侧连线 ----------
