\draw[slow] (interp.east) -- (interp.east -| host.west);
\draw[flow] (host) -- (state);

% ---------- profiling -> 编译队列 ----------
\draw[bg]  (interp.south) -- (prof.north) node[lbl, midway, right=1pt] {count\texttt{++}, gas};
\draw[bgl] (prof.east) -- (14.3,3.85);
\draw[bg]  (14.3,3.85) -- (queue.north) node[lbl, pos=0.05, above left=-1pt] {enqueue};

% ---------- 编译管线 ----------
\draw[bg] (queue.west) -- (bb.east);
\draw[bg] (bb.west)    -- (ir.east);
\draw[bg] (ir.south)   -- (p1.north);
\draw[bg] (p1.south)   -- (p2.north);
\draw[bg] (p2.south)   -- (p3.north);
\draw[bg] (p3.west)    -- (jit.east);

% ---------- 回填 Code cache（U 型回路拆 3 段直线） ----------
\draw[bgl] (jit.north) -- (0.6,4.60);
\draw[bgl] (0.6,4.60)  -- (6.5,4.60);
\draw[bg]  (6.5,4.60)  -- (cache.south);
\node[lbl, above] at (3.4,4.60) {install native code};

\end{tikzpicture}
\caption{Overview of our EVM execution engine. Bold solid arrows mark the JIT
fast path, dashed arrows the interpreter slow path, and dotted arrows the
asynchronous background compilation path; both execution paths share one
host interface. The shaded block is our SSA IR and its three optimization
passes.}
\label{fig:overview}
\end{figure*}
```

三点你自己过一遍：整图约 17.2 × 9.3 cm，`\textwidth` 是 17.78 cm，应该不会 overfull，真溢出就把 `state` 挪到 14.6；`hit` / `miss` 两个标签是按肘形线的拐点手放的，编出来偏了直接改那一行的坐标；想压高度就缩 `p1/p2/p3` 的 y 间距（现在 0.8）。

没有 Bash/Write 权限，也没有 TeX——按 skill 的降级路径走：设计块 + 完整代码直接给你，编译验证和几何自检这次跳过。图档按「中等档骨架」定：主流 + 分区 + 标注，无嵌入可视化、无 legend 面板。

